  const cdFall = u2.cd4 - u10.cd4, cdFallPct = (100 * cdFall) / u2.cd4, cdRate = cdFall / 8;
  const vl2 = sig2(10 ** u2.vlLog), vl10 = sig2(10 ** u10.vlLog), vlFactor = 10 ** (u10.vlLog - u2.vlLog);
